import sys
from math import gcd
from collections import defaultdict

def euler_totient(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def main():
    MOD = 10**9 + 7
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:n+1]))
    edges = [(int(input[2+i*2]), int(input[3+i*2])) for i in range(n-1)]

    adj = defaultdict(list)
    for x, y in edges:
        adj[x].append(y)
        adj[y].append(x)

    depth = [0] * (n + 1)
    size = [0] * (n + 1)
    parent = [0] * (n + 1)

    def dfs(u, p):
        parent[u] = p
        size[u] = 1
        for v in adj[u]:
            if v != p:
                depth[v] = depth[u] + 1
                size[u] += dfs(v, u)
        return size[u]

    dfs(1, 0)

    def reroot(u, p):
        for v in adj[u]:
            if v != p:
                reroot(v, u)
        for v in adj[u]:
            if v != p:
                size[u] -= size[v]
                size[v] += size[u]

    reroot(1, 0)

    total_sum = 0
    for u in range(1, n + 1):
        for v in adj[u]:
            if parent[u] == v:
                continue
            d = abs(depth[u] - depth[v])
            total_sum += euler_totient(a[u] * a[v]) * d * size[u] * size[v]

    P = total_sum
    Q = n * (n - 1) // 2
    result = (P * pow(Q, -1, MOD) - 1) % MOD
    print(result)

main()
